<template><section><div class="mb-6"><h1 class="text-2xl font-bold">{{t('inbounds.title')}}</h1><p class="mt-1 text-sm text-slate-500">Only Cloudflare-native WebSocket transports are listed.</p></div><div class="grid gap-4 lg:grid-cols-2"><div v-for="c in configs" :key="c.id" class="card"><div class="flex items-start justify-between"><div><div class="font-semibold">{{c.remark||'3X-UI'}}</div><div class="mt-1 text-xs text-slate-500">{{c.protocol}} · {{c.host}}</div></div><span :class="c.active?'text-emerald-400':'text-slate-500'">● {{c.active?t('common.enabled'):t('common.disabled')}}</span></div><div class="mt-4 rounded-xl bg-black/20 p-3 font-mono text-xs text-slate-400">{{c.path}}</div><div class="mt-3 flex justify-end gap-2"><button class="btn-ghost" @click="toggle(c)">{{c.active?t('inbounds.disable'):t('inbounds.enable')}}</button><button class="btn-danger" @click="remove(c.id)">{{t('common.delete')}}</button></div></div></div><div v-if="!configs.length" class="card text-center text-sm text-slate-600">{{t('common.noData')}}</div></section></template>
<script setup lang="ts">import{ref}from'vue';import{useI18n}from'vue-i18n';import{api}from'../api/client';const{t}=useI18n(),configs=ref<any[]>([]);async function load(){configs.value=(await api.get<any>('/configs')).configs||[]}async function toggle(c:any){await api.patch(`/configs/${c.id}`,{active:!c.active});await load()}async function remove(id:number){if(confirm('Delete this config?')){await api.delete(`/configs/${id}`);await load()}}load();</script>
